#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-08
# Rewritten: 2026-08-29 (#3541)
# scripts/probe-command-discovery.sh: the native-surfacing tripwire.
#
# QUESTION IT ANSWERS
# -------------------
# Does the running Claude Code surface the plugin's user-invocable skills as
# `/ork:<name>` slash commands WITHOUT command wrappers? Since #3541 the built
# plugin ships NO commands/ for Claude Code (the wrappers live under
# .cursor-plugin/commands/ for the Cursor host only), on the strength of one
# measurement: on 2.1.251, `claude -p "/ork:glyph hello"` expands to
# `<command-name>/ork:glyph</command-name>` in the first model request with the
# wrappers removed, byte-identical to with them. This script re-asks the binary,
# so the day CC stops surfacing skills natively the answer is red here rather
# than in a user's palette.
#
# METHOD
# ------
# The built plugin is loaded with --plugin-dir into a `claude -p` run whose
# model is a loopback stub of the Messages API (tests/ci/restricted-smoke/
# stub-anthropic-api.mjs): no login, no spend. The stub logs every request's
# message text; the probe greps the FIRST model request for the expanded
# command tag. The previous method (a "Total plugin commands loaded" debug
# counter) stopped existing before 2.1.251 and reported CANNOT OBSERVE.
#
# EXIT CODES
#   0  native surfacing works: the skill expanded without wrappers
#   1  REGRESSED: the literal "/ork:<skill>" reached the model unexpanded.
#      Restore the CC commands/ wrappers in scripts/build-plugins.sh.
#   2  CANNOT OBSERVE: binary/plugin/stub missing, or no model request logged.
#
# Runs locally / workflow_dispatch only. Invoke as: npm run verify:cc-commands
# Env: CLAUDE_BIN (default claude), PROBE_SKILL (default glyph)

set -euo pipefail
trap 'echo "[probe-command-discovery] failed at line $LINENO" >&2' ERR

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PLUGIN="$ROOT/plugins/ork"
STUB="$ROOT/tests/ci/restricted-smoke/stub-anthropic-api.mjs"
CLAUDE_BIN="${CLAUDE_BIN:-claude}"
SKILL="${PROBE_SKILL:-glyph}"

command -v "$CLAUDE_BIN" >/dev/null || { echo "CANNOT OBSERVE: $CLAUDE_BIN not on PATH" >&2; exit 2; }
[ -f "$PLUGIN/.claude-plugin/plugin.json" ] || { echo "CANNOT OBSERVE: $PLUGIN not built (npm run build)" >&2; exit 2; }
[ -f "$PLUGIN/skills/$SKILL/SKILL.md" ] || { echo "CANNOT OBSERVE: skill $SKILL not in the built plugin" >&2; exit 2; }
[ -f "$STUB" ] || { echo "CANNOT OBSERVE: stub $STUB missing" >&2; exit 2; }
if [ -d "$PLUGIN/commands" ]; then
  echo "CANNOT OBSERVE: $PLUGIN/commands exists, so an expansion could come from a wrapper; the probe needs the wrapper-free plugin" >&2
  exit 2
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/probe-cmd.XXXXXX")"
STUB_PID=""
cleanup() {
  # silent: post-cleanup
  if [ -n "$STUB_PID" ]; then kill "$STUB_PID" 2>>"$WORK/stub.log" || true; fi
  rm -rf "$WORK"
}
trap cleanup EXIT
mkdir -p "$WORK/home" "$WORK/proj"

STUB_LOG="$WORK/requests.jsonl" STUB_PORT_FILE="$WORK/port" STUB_GREP="<command-name>/ork:${SKILL}</command-name>" \
  node "$STUB" > "$WORK/stub.log" 2>&1 &
STUB_PID=$!
for _ in $(seq 1 50); do [ -s "$WORK/port" ] && break; sleep 0.1; done
[ -s "$WORK/port" ] || { echo "CANNOT OBSERVE: stub did not start" >&2; cat "$WORK/stub.log" >&2; exit 2; }
PORT="$(cat "$WORK/port")"

echo "probe-command-discovery: $("$CLAUDE_BIN" --version 2>>"$WORK/stub.log" || echo unknown), skill /ork:$SKILL, wrapper-free plugin"
set +e
( cd "$WORK/proj" && env -u CLAUDECODE -u CLAUDE_CODE_OAUTH_TOKEN -u CLAUDE_CONFIG_DIR \
    HOME="$WORK/home" ANTHROPIC_BASE_URL="http://127.0.0.1:$PORT" ANTHROPIC_API_KEY="probe-stub" DISABLE_TELEMETRY=1 \
    "$CLAUDE_BIN" -p "/ork:$SKILL probe" --plugin-dir "$PLUGIN" --output-format json --max-turns 1 \
    > "$WORK/result.json" 2> "$WORK/stderr.txt" < /dev/null )
RC=$?
set -e
[ "$RC" -eq 0 ] || { echo "CANNOT OBSERVE: claude exited $RC" >&2; head -c 600 "$WORK/stderr.txt" >&2; exit 2; }

VERDICT="$(node -e '
const fs = require("fs");
const rows = fs.readFileSync(process.argv[1], "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
const main = rows.filter((r) => r.method === "POST" && /\/v1\/messages/.test(r.path) && Array.isArray(r.tools) && r.tools.length > 5);
if (!main.length) { process.stdout.write("UNOBSERVED"); process.exit(0); }
process.stdout.write(main[0].grep_hit ? "EXPANDED" : "LITERAL");
' "$WORK/requests.jsonl")"

case "$VERDICT" in
  EXPANDED) echo "  first model request carries <command-name>/ork:$SKILL</command-name>: native surfacing works"; exit 0 ;;
  LITERAL)  echo "  REGRESSED: /ork:$SKILL reached the model unexpanded; CC no longer surfaces skills natively, restore the commands/ wrappers" >&2; exit 1 ;;
  *)        echo "CANNOT OBSERVE: no model request with a tool list was logged" >&2; exit 2 ;;
esac
